   609  static GVariant *
   610  parse_res_txt (const guint8  *answer,
   611                 const guint8  *end,
   612                 const guint8 **p)
   613  {
   614    GVariant *record;
   615    GPtrArray *array;
   616    const guint8 *at = *p;
   617    gsize len;
   618
   619    array = g_ptr_array_new_with_free_func (g_free);
   620    while (at < end)
   621      {
   622        len = *(at++);
   623        if (len > (gsize) (end - at))
   624          break;
   625        g_ptr_array_add (array, g_strndup ((gchar *)at, len));
   626        at += len;
   627      }
   628
   629    *p = at;
   630    record = g_variant_new ("(@as)",
   631                            g_variant_new_strv ((const gchar **)array->pdata, array->len));
   632    g_ptr_array_free (array, TRUE);
   633    return record;
   634  }
