   655  GList *
   656  g_resolver_records_from_res_query (const gchar      *rrname,
   657                                     gint              rrtype,
   658                                     const guint8     *answer,
   659                                     gssize            len,
   660                                     gint              herr,
   661                                     GError          **error)
   662  {
   663    gint count;
   664    gchar namebuf[1024];
   665    const guint8 *end, *p;
   666    guint16 type, qclass, rdlength;
   667    const HEADER *header;
   668    GList *records;
   669    GVariant *record;
   670
   671    if (len <= 0)
   672      {
   673        if (len == 0 || herr == HOST_NOT_FOUND || herr == NO_DATA)
   674          {
   675            g_set_error (error, G_RESOLVER_ERROR, G_RESOLVER_ERROR_NOT_FOUND,
   676                         _("No DNS record of the requested type for “%s”"), rrname);
   677          }
   678        else if (herr == TRY_AGAIN)
   679          {
   680            g_set_error (error, G_RESOLVER_ERROR, G_RESOLVER_ERROR_TEMPORARY_FAILURE,
   681                         _("Temporarily unable to resolve “%s”"), rrname);
   682          }
   683        else
   684          {
   685            g_set_error (error, G_RESOLVER_ERROR, G_RESOLVER_ERROR_INTERNAL,
   686                         _("Error resolving “%s”"), rrname);
   687          }
   688
   689        return NULL;
   690      }
   691
   692    records = NULL;
   693
   694    header = (HEADER *)answer;
   695    p = answer + sizeof (HEADER);
   696    end = answer + len;
   697
   698    /* Skip query */
   699    count = ntohs (header->qdcount);
   700    while (count-- && p < end)
   701      {
   702        p += dn_expand (answer, end, p, namebuf, sizeof (namebuf));
   703        p += 4;
   704
   705        /* To silence gcc warnings */
   706        namebuf[0] = namebuf[1];
   707      }
   708
   709    /* Read answers */
   710    count = ntohs (header->ancount);
   711    while (count-- && p < end)
   712      {
   713        p += dn_expand (answer, end, p, namebuf, sizeof (namebuf));
   714        GETSHORT (type, p);
   715        GETSHORT (qclass, p);
   716        p += 4; /* ignore the ttl (type=long) value */
   717        GETSHORT (rdlength, p);
   718
   719        if (type != rrtype || qclass != C_IN)
   720          {
   721            p += rdlength;
   722            continue;
   723          }
   724
   725        switch (rrtype)
   726          {
   727          case T_SRV:
   728            record = parse_res_srv (answer, end, &p);
   729            break;
   730          case T_MX:
   731            record = parse_res_mx (answer, end, &p);
   732            break;
   733          case T_SOA:
   734            record = parse_res_soa (answer, end, &p);
   735            break;
   736          case T_NS:
   737            record = parse_res_ns (answer, end, &p);
   738            break;
   739          case T_TXT:
   740            record = parse_res_txt (answer, p + rdlength, &p);
   741            break;
   742          default:
   743            g_warn_if_reached ();
   744            record = NULL;
   745            break;
   746          }
   747
   748        if (record != NULL)
   749          records = g_list_prepend (records, record);
   750      }
   751
   752    if (records == NULL)
   753      {
   754        g_set_error (error, G_RESOLVER_ERROR, G_RESOLVER_ERROR_NOT_FOUND,
   755                     _("No DNS record of the requested type for “%s”"), rrname);
   756
   757        return NULL;
   758      }
   759    else
   760      return records;
   761  }
